paragraph.math:
$$\begin{array}{l}
  {{\int{x\sin xdx}} = {f(x)g(x) - {\int{g(x)f^{\prime}(x)dx}}}} \\
  {\phantom{\int{x\sin xdx}} = {x\left( {- \cos x} \right) - {\int{\left( {- \cos x} \right)dx}}}} \\
  {\phantom{\int{x\sin xdx}} = {- x\cos x + {\int{\cos xdx}}}} \\
  {\phantom{\int{x\sin xdx}} = {- x\cos x + \sin x + C}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int l}nxdx} = {x\ln x - {\int{x \cdot \frac{1}{x}{dx}}}}} \\
  {\phantom{{\int l}nxdx} = {x\ln x - {\int{dx}}}} \\
  {\phantom{{\int l}nxdx} = {x\ln x - x + C}}
  \end{array}$$

$$\begin{array}{l}
  {\int{te^{ t}dt = te^{ t} - {\int{e^{ t}dt}}}} \\
  {\phantom{\int{te^{ t}dt}}{= te^{ t} - e^{ t} + C}}
  \end{array}$$

$$\begin{array}{l}
  {{\int t^{2}}e^{ t}dt = {t^{2}e^{ t} - 2{\int{te^{ t}dt}}}} \\
  {\phantom{{\int t^{2}}e^{ t}dt} = {t^{2}e^{ t} - 2{({te^{ t} - e^{ t} + C})}}} \\
  {\phantom{{\int t^{2}}e^{ t}dt} = {t^{2}e^{ t} - 2te^{ t} + 2e^{ t} + C_{1}\qquad{where}C_{1} = - 2C}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int{\cos^{3}x}}dx} = {\int\cos^{2}x \cdot \cos xdx = \int{({1 - \sin^{2}x})}\cos xdx}} \\
  {\phantom{{\int{\cos^{3}x}}dx} = {{\int{({1 - u^{2}})}}du = u - \frac{1}{3}u^{3} + C}} \\
  {\phantom{{\int{\cos^{3}x}}dx} = {\sin x - \frac{1}{3}\sin^{3}x + C}}
  \end{array}$$

$$\begin{array}{l}
  {{\int\sec xdx} = {\int\sec x\frac{\sec x + \tan x}{\sec x + \tan x}dx}} \\
  {\phantom{\int\sec xdx} = {\int\frac{\sec^{2}x + \sec x\tan x}{\sec x + \tan x}dx}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int{\tan^{3}x}}dx} = {{\int{\tan x}}\tan^{2}xdx = {\int{\tan x}}{({\sec^{2}x - 1})}dx}} \\
  {\phantom{{\int{\tan^{3}x}}dx} = {{\int{\tan x}}\sec^{2}xdx - {\int{\tan x}}dx}} \\
  {\phantom{{\int{\tan^{3}x}}dx} = {\frac{1}{2}\tan^{2}x - \ln\left| {\sec x} \right| + C}}
  \end{array}$$

$$\begin{array}{rllrll}
  u & = & {\sec x} & {\quad dv} & = & {\sec^{2}xdx} \\
  {du} & = & {\sec x\tan xdx} & {\quad v} & = & {\tan x}
  \end{array}$$

$$\begin{array}{l}
  {{{\int{\sec^{3}x}}dx} = {\sec x\tan x} - {{\int{\sec x}}\tan^{2}xdx}} \\
  {\phantom{{\int{\sec^{3}x}}dx} = {\sec x\tan x} - {{\int{\sec x}}{({\sec^{2}x - 1})}dx}} \\
  {\phantom{{\int{\sec^{3}x}}dx} = {\sec x\tan x} - {{\int{\sec^{3}x}}dx + {\int{\sec x}}dx}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int{\frac{\sqrt{9 - x^{2}}}{x^{2}}}}dx} = {{\int{\frac{3\cos\theta}{9\sin^{2}\theta}}}3\cos\theta d\theta}} \\
  {\phantom{{\int{\frac{\sqrt{9 - x^{2}}}{x^{2}}}}dx} = {{\int{\frac{\cos^{2}\theta}{\sin^{2}\theta}}}d\theta = {\int{\cot^{2}}}\theta d\theta}} \\
  {\phantom{{\int{\frac{\sqrt{9 - x^{2}}}{x^{2}}}}dx} = {{\int{({\csc^{2}\theta - 1})}}d\theta}} \\
  {\phantom{{\int{\frac{\sqrt{9 - x^{2}}}{x^{2}}}}dx} = {- \cot\theta - \theta + C}}
  \end{array}$$

$$\begin{array}{l}
  {{\int{\frac{dx}{\sqrt{x^{2} - a^{2}}}}} = \ln\left| {\frac{x}{a} + \frac{\sqrt{x^{2} - a^{2}}}{a}} \right| + C} \\
  {\phantom{\int{\frac{dx}{\sqrt{x^{2} - a^{2}}}}}{= \ln\left| {x + \sqrt{x^{2} - a^{2}}} \right| - \ln a + C}}
  \end{array}$$

$$\begin{array}{l}
  {{\int\frac{dx}{x^{2} - a^{2}}} = {\frac{1}{2a}{\int\left( {\frac{1}{x - a} - \frac{1}{x + a}} \right)}dx}} \\
  {\phantom{\int\frac{dx}{x^{2} - a^{2}}} = {\frac{1}{2a}\left( {\ln\left| {x - a} \right| - \ln\left| {x + a} \right|} \right) + C}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int\frac{x^{4} - 2x^{2} + 4x + 1}{x^{3} - x^{2} - x + 1}}dx} = {{\int\left\lbrack {x + 1 + \frac{1}{x - 1} + \frac{2}{\left( {x - 1} \right)^{2}} - \frac{1}{x + 1}} \right\rbrack}dx}} \\
  {\phantom{{\int\frac{x^{4} - 2x^{2} + 4x + 1}{x^{3} - x^{2} - x + 1}}dx} = {\frac{x^{2}}{2} + x + \ln\left| {x - 1} \right| - \frac{2}{x - 1} - \ln\left| {x + 1} \right| + K}} \\
  {\phantom{{\int\frac{x^{4} - 2x^{2} + 4x + 1}{x^{3} - x^{2} - x + 1}}dx} = \left. \frac{x^{2}}{2} + x - \frac{2}{x - 1} + \ln \middle| \frac{x - 1}{x + 1} \right| + K}
  \end{array}$$

$$\begin{matrix}
  {A = - 1,\quad B = \frac{1}{8},\quad C = D = - 1,} \\
  {E = \frac{15}{8},\quad F = - \frac{1}{8},\quad G = H = \frac{3}{4},} \\
  {I = - \frac{1}{2},\quad J = \frac{1}{2}}
  \end{matrix}$$

$$\begin{array}{l}
  {{\int\frac{dx}{1 - \cos x}} = {{\int{\frac{1}{1 - \cos x} \cdot \frac{1 + \cos x}{1 + \cos x}}}dx = {\int\frac{1 + \cos x}{1 - \cos^{2}x}}dx}} \\
  {\phantom{\int\frac{dx}{1 - \cos x}} = {{\int\frac{1 + \cos x}{\sin^{2}x}}dx = {\int\left( {\csc^{2}x + \frac{\cos x}{\sin^{2}x}} \right)}dx}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int\sqrt{\frac{1 - x}{1 + x}}}dx} = {{\int\frac{1 - x}{\sqrt{1 - x^{2}}}}dx}} \\
  {\phantom{{\int\sqrt{\frac{1 - x}{1 + x}}}dx} = {{\int\frac{1}{\sqrt{1 - x^{2}}}}dx - {\int\frac{x}{\sqrt{1 - x^{2}}}}dx}} \\
  {\phantom{{\int\sqrt{\frac{1 - x}{1 + x}}}dx} = {\sin^{- 1}x + \sqrt{1 - x^{2}} + C}}
  \end{array}$$

$$\begin{matrix}
  {{{\int{x^{2}\cos x}}dx} = {x^{2}\sin x - 2{\int{x\sin x}}dx}} \\
  {\phantom{{\int{x^{2}\cos x}}dx} = {x^{2}\sin x - 2\left( {\sin x - x\cos x} \right) + K}}
  \end{matrix}$$

$$\begin{array}{l}
  {{{arcsinh}\frac{\sqrt{3}}{3}\left( {1 + x} \right)} = {\ln\left\lbrack {\frac{\sqrt{3}}{3}\left( {1 + x} \right) + \sqrt{\frac{1}{3}\left( {1 + x} \right)^{2} + 1}} \right\rbrack}} \\
  {\phantom{{arcsinh}\frac{\sqrt{3}}{3}\left( {1 + x} \right)} = {\ln\frac{1}{\sqrt{3}}\left\lbrack {1 + x + \sqrt{\left( {1 + x} \right)^{2} + 3}} \right\rbrack}} \\
  {\phantom{{arcsinh}\frac{\sqrt{3}}{3}\left( {1 + x} \right)} = {\ln\frac{1}{\sqrt{3}} + \ln\left( {x + 1 + \sqrt{x^{2} + 2x + 4}} \right)}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{a}^{b}{f(x)dx}} \approx {\frac{1}{2}\left\lbrack {\sum\limits_{i = 1}^{n}{f(x_{i - 1})\Delta x + {\sum\limits_{i = 1}^{n}{f(x_{i})\Delta x}}}} \right\rbrack = \frac{\Delta x}{2}\left\lbrack {\sum\limits_{i = 1}^{n}\left( {f{(x_{i - 1})} + f(x_{i})} \right)} \right\rbrack}} \\
  {\phantom{\int_{a}^{b}{f(x)dx}} = {\frac{\Delta x}{2}\left\lbrack {\left( {f\left( x_{0} \right) + f\left( x_{1} \right)} \right) + \left( {f\left( x_{1} \right) + f\left( x_{2} \right)} \right) + \cdots + \left( {f\left( x_{n - 1} \right) + f\left( x_{n} \right)} \right)} \right\rbrack}} \\
  {\phantom{\int_{a}^{b}{f(x)dx}} = {\frac{\Delta x}{2}\left\lbrack {\left( {f\left( x_{0} \right) + 2f\left( x_{1} \right)} \right) + 2f(x_{2}) + \cdots + 2f(x_{n - 1}) + f(x_{n})} \right\rbrack}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{- h}^{h}{{({Ax^{2} + Bx + C})}dx}} = 2{\int_{0}^{h}{{({Ax^{2} + C})}dx =}}2\left\lbrack {A\frac{x^{3}}{3} + Cx} \right\rbrack_{0}^{h}} \\
  {\phantom{\int_{- h}^{h}{\left( {Ax^{2} + Bx + C} \right)dx}} = 2\left( {A\frac{h^{3}}{3} + Ch} \right) = \frac{h}{3}(2Ah^{2} + 6C)}
  \end{array}$$

$$\begin{array}{rcl}
  y_{0} & = & {A\left( {- h} \right)^{2} + B\left( {- h} \right) + C = Ah^{2} - Bh + C} \\
  y_{1} & = & C \\
  y_{2} & = & {Ah^{2} + Bh + C}
  \end{array}$$

$$\begin{array}{l}
  {{{\int_{t}^{0}{xe^{ x}}}dx} = {\left. {xe^{ x}} \right\rbrack_{t}^{0} - {\int_{t}^{0}e^{ x}}dx}} \\
  {\phantom{{\int_{t}^{0}{xe^{ x}}}dx} = {- te^{ t} - 1 + e^{ t}}}
  \end{array}$$

$$\begin{array}{l}
  {{\lim\limits_{t\rightarrow - \infty}te^{ t}} = {\lim\limits_{t\rightarrow - \infty}\frac{t}{e^{- t}} = \lim\limits_{t\rightarrow - \infty}\frac{1}{- e^{- t}}}} \\
  {\phantom{\lim\limits_{t\rightarrow - \infty}te^{ t}} = {\underset{t\rightarrow - \infty}{\lim}{({- e^{ t}})} = 0}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int_{- \infty}^{0}{xe^{ x}}}dx} = {\lim\limits_{t\rightarrow - \infty}{({- te^{ t} - 1 + e^{ t}})}}} \\
  {\phantom{{\int_{- \infty}^{0}{xe^{ x}}}dx} = {- 0 - 1 + 0 = - 1}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int_{0}^{\infty}\frac{1}{1 + x^{2}}}dx} = {\lim\limits_{t\rightarrow\infty}{\int_{0}^{t}\frac{dx}{1 + x^{2}}} = \lim\limits_{t\rightarrow\infty}\left. {\tan^{- 1}x} \right\rbrack_{0}^{t}}} \\
  {\phantom{{\int_{0}^{\infty}\frac{1}{1 + x^{2}}}dx} = {\lim\limits_{t\rightarrow\infty}\left( {\tan^{- 1}t - \tan^{- 1}0} \right) = \lim\limits_{t\rightarrow\infty}\tan^{- 1}t = \frac{\pi}{2}}} \\
  {{{\int_{- \infty}^{0}\frac{1}{1 + x^{2}}}dx} = {\lim\limits_{t\rightarrow - \infty}{\int_{t}^{0}\frac{dx}{1 + x^{2}}} = \lim\limits_{t\rightarrow - \infty}\left. {\tan^{- 1}x} \right\rbrack_{t}^{0}}} \\
  {\phantom{{\int_{- \infty}^{0}\frac{1}{1 + x^{2}}}dx} = {\lim\limits_{t\rightarrow - \infty}\left( {\tan^{- 1}0 - \tan^{- 1}t} \right) = 0 - \left( {- ‍\frac{\pi}{2}} \right) = \frac{\pi}{2}}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int_{0}^{\pi \slash 2}{\sec x}}dx} = {\lim\limits_{t\rightarrow{({\pi \slash 2})}^{-}}{\int_{0}^{t}{\sec x}}dx = \lim\limits_{t\rightarrow{({\pi \slash 2})}^{-}}\left. {\ln\left| {\sec x + \tan x} \right|} \right\rbrack_{0}^{t}}} \\
  {\phantom{{\int_{0}^{\pi \slash 2}{\sec x}}dx} = {\lim\limits_{t\rightarrow{({\pi \slash 2})}^{-}}\left\lbrack {\ln\left( {\sec t + \tan t} \right) - \ln 1} \right\rbrack = \infty}}
  \end{array}$$

$$\begin{array}{l}
  {{{\int_{t}^{1}{\ln x}}dx} = {\left. {x\ln x} \right\rbrack_{t}^{1} - {\int_{t}^{1}{dx}}}} \\
  {\phantom{{\int_{t}^{1}{\ln x}}dx} = {1\ln 1 - t\ln t - \left( {1 - t} \right) = - t\ln t - 1 + t}}
  \end{array}$$
